CREATE TYPE "SafetyCaseLifecycle" AS ENUM ('DETECTED','HANDOFF_INITIATED','ACKNOWLEDGED','CLINICAL_REVIEW_IN_PROGRESS','PLAN_ESTABLISHED','RESOLVED','ESCALATED_TO_EMERGENCY','RESOLVED_EXTERNAL_HANDOFF');
CREATE TYPE "SafetyCaseDomain" AS ENUM ('WITHDRAWAL_OR_MEDICAL','SUICIDE_OR_SELF_HARM','PREGNANCY','OTHER_SUBSTANCE','ROUTINE_MEDICAL_CONTEXT');
CREATE TYPE "SafetyDisposition" AS ENUM ('SAFE_TO_CONTINUE_STANDARD_MONITORING','SAFE_TO_CONTINUE_WITH_RESTRICTIONS','CONTINUE_CLINICAL_HANDOFF','EMERGENCY_EXTERNAL_MANAGEMENT','MONITORING_TEMPORARILY_PAUSED');
CREATE TABLE "safety_cases" ("id" UUID NOT NULL, "patient_id" UUID NOT NULL, "domain" "SafetyCaseDomain" NOT NULL, "source_safety_evaluation_result_id" UUID NOT NULL, "severity" VARCHAR(32) NOT NULL, "gate_status" VARCHAR(32) NOT NULL, "owner_role" VARCHAR(64) NOT NULL, "lifecycle" "SafetyCaseLifecycle" NOT NULL DEFAULT 'DETECTED', "version" INTEGER NOT NULL DEFAULT 1, "detected_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "resolved_at" TIMESTAMPTZ(6), "current_restriction_version_id" UUID, "current_route_snapshot" JSONB, "route_status" VARCHAR(32) NOT NULL, "route_profile_id" UUID, "route_profile_logical_version" INTEGER, CONSTRAINT "safety_cases_pkey" PRIMARY KEY ("id"), CONSTRAINT "safety_cases_patient_fk" FOREIGN KEY ("patient_id") REFERENCES "patient_profiles"("patient_id") ON DELETE RESTRICT, CONSTRAINT "safety_cases_evaluation_fk" FOREIGN KEY ("source_safety_evaluation_result_id") REFERENCES "safety_evaluation_results"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "safety_cases_patient_domain_active_key" ON "safety_cases"("patient_id","domain") WHERE "resolved_at" IS NULL;
CREATE TABLE "safety_case_restriction_versions" ("id" UUID NOT NULL, "case_id" UUID NOT NULL, "version" INTEGER NOT NULL, "gate_status" VARCHAR(32) NOT NULL, "allowed_subjective_interventions" JSONB NOT NULL, "monitoring_prompt_policy" VARCHAR(32) NOT NULL, "goal_change_allowed" BOOLEAN NOT NULL, "reassessment_due_at" TIMESTAMPTZ(6), "source_disposition_id" UUID, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "created_by_user_id" UUID NOT NULL, CONSTRAINT "safety_case_restriction_versions_pkey" PRIMARY KEY ("id"), CONSTRAINT "safety_case_restrictions_case_fk" FOREIGN KEY ("case_id") REFERENCES "safety_cases"("id") ON DELETE RESTRICT, CONSTRAINT "safety_case_restrictions_key" UNIQUE ("case_id","version"));
ALTER TABLE "safety_cases" ADD CONSTRAINT "safety_cases_current_restriction_fk" FOREIGN KEY ("current_restriction_version_id") REFERENCES "safety_case_restriction_versions"("id") ON DELETE RESTRICT;
CREATE TABLE "safety_case_dispositions" ("id" UUID NOT NULL, "case_id" UUID NOT NULL, "version" INTEGER NOT NULL, "disposition" "SafetyDisposition" NOT NULL, "restrictions" JSONB, "actor_id" UUID NOT NULL, "actor_role" VARCHAR(64) NOT NULL, "reason" TEXT NOT NULL, "source_case_version" INTEGER NOT NULL, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "safety_case_dispositions_pkey" PRIMARY KEY ("id"), CONSTRAINT "safety_case_dispositions_case_fk" FOREIGN KEY ("case_id") REFERENCES "safety_cases"("id") ON DELETE RESTRICT, CONSTRAINT "safety_case_dispositions_key" UNIQUE ("case_id","version"));
CREATE TABLE "safety_case_lifecycle_events" ("id" UUID NOT NULL, "case_id" UUID NOT NULL, "from_state" "SafetyCaseLifecycle", "to_state" "SafetyCaseLifecycle" NOT NULL, "actor_id" UUID NOT NULL, "reason" TEXT, "request_id" VARCHAR(128), "occurred_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "safety_case_lifecycle_events_pkey" PRIMARY KEY ("id"), CONSTRAINT "safety_case_lifecycle_events_case_fk" FOREIGN KEY ("case_id") REFERENCES "safety_cases"("id") ON DELETE RESTRICT);
CREATE OR REPLACE FUNCTION prevent_safety_case_history_change() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'safety case historical records are immutable'; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER safety_case_restrictions_append_only BEFORE UPDATE OR DELETE ON "safety_case_restriction_versions" FOR EACH ROW EXECUTE FUNCTION prevent_safety_case_history_change();
CREATE TRIGGER safety_case_dispositions_append_only BEFORE UPDATE OR DELETE ON "safety_case_dispositions" FOR EACH ROW EXECUTE FUNCTION prevent_safety_case_history_change();
CREATE TRIGGER safety_case_lifecycle_events_append_only BEFORE UPDATE OR DELETE ON "safety_case_lifecycle_events" FOR EACH ROW EXECUTE FUNCTION prevent_safety_case_history_change();
